// scripts/seed.js
//
// Standalone script (plain Node, CommonJS — deliberately doesn't import
// Next.js internals or the app's ESM model files) that seeds fixed demo
// data into whatever database MONGODB_URL points at. Safe to re-run —
// everything is upserted, not duplicated.
//
// Usage:
//   npm run seed
//   (equivalent to: node --env-file=.env.local scripts/seed.js)

const mongoose = require("mongoose");
const bcrypt = require("bcryptjs");
const { v2: cloudinary } = require("cloudinary");

const MONGODB_URL = process.env.MONGODB_URL;
if (!MONGODB_URL) {
  console.error("MONGODB_URL is not set. Add it to .env.local first, then re-run `npm run seed`.");
  process.exit(1);
}

const cloudinaryMissing = process.env.CLOUDINARY_URL
  ? []
  : ["CLOUDINARY_CLOUD_NAME", "CLOUDINARY_API_KEY", "CLOUDINARY_API_SECRET"]
      .filter((name) => !process.env[name]);
if (cloudinaryMissing.length) {
  console.error(`Missing Cloudinary configuration: ${cloudinaryMissing.join(", ")}.`);
  process.exit(1);
}

cloudinary.config(process.env.CLOUDINARY_URL
  ? { secure: true }
  : {
      cloud_name: process.env.CLOUDINARY_CLOUD_NAME,
      api_key: process.env.CLOUDINARY_API_KEY,
      api_secret: process.env.CLOUDINARY_API_SECRET,
      secure: true,
    });

// Schemas are redefined here (not imported from ../models) so this script
// has zero dependency on the app's ESM module graph or Next.js — it only
// needs `mongoose`, and runs as a completely separate Node process.
const UserSchema = new mongoose.Schema(
  {
    name: String,
    email: { type: String, unique: true, lowercase: true, trim: true },
    password: String,
    role: { type: String, enum: ["admin", "team_member"], default: "admin" },
    createdBy: { type: mongoose.Schema.Types.ObjectId, ref: "User" },
  },
  { timestamps: true }
);

const EventSchema = new mongoose.Schema(
  {
    name: String,
    createdBy: { type: mongoose.Schema.Types.ObjectId, ref: "User" },
    assignedTeam: [{ type: mongoose.Schema.Types.ObjectId, ref: "User" }],
    galleryPublished: { type: Boolean, default: false },
    galleryPinHash: String,
    gallerySlug: { type: String, unique: true, sparse: true },
    coverPhotoStorageProvider: String,
    coverPhotoCloudinaryPublicId: String,
    coverPhotoCloudinaryAssetId: String,
    coverPhotoCloudinaryVersion: Number,
    coverPhotoCloudinaryFormat: String,
    coverPhotoContentType: String,
  },
  { timestamps: true }
);

const PhotoSchema = new mongoose.Schema(
  {
    eventId: { type: mongoose.Schema.Types.ObjectId, ref: "Event" },
    uploadedBy: { type: mongoose.Schema.Types.ObjectId, ref: "User" },
    filename: String,
    storageProvider: String,
    cloudinaryPublicId: String,
    cloudinaryAssetId: String,
    cloudinaryVersion: Number,
    cloudinaryFormat: String,
    gridfsId: mongoose.Schema.Types.ObjectId,
    contentType: String,
    fileSize: Number,
    selectedForGallery: { type: Boolean, default: false },
  },
  { timestamps: true }
);

const User = mongoose.models.User || mongoose.model("User", UserSchema);
const Event = mongoose.models.Event || mongoose.model("Event", EventSchema);
const Photo = mongoose.models.Photo || mongoose.model("Photo", PhotoSchema);

const PORT = process.env.PORT || 5000;

const DEMO = {
  admin: { name: "Priya Shah", email: "admin@trizen.demo", password: "Trizen@Admin123" },
  team: { name: "Rohit Mehta", email: "team@trizen.demo", password: "Trizen@Team123" },
  eventName: "Arjun & Priya Wedding", // same example event the challenge PDF itself uses
  slug: "abc123", // same example slug the PDF's section 5 uses
  pin: "482917", // same example PIN the PDF's section 5 uses
};

// Three small (~25KB) generated JPEGs so the seeded gallery has something
// real to look at, without needing a photo file supplied from outside.
const SAMPLE_PHOTOS = [
  { filename: "arrival.jpg", base64: "" },
  { filename: "ceremony.jpg", base64: "" },
  { filename: "reception.jpg", base64: "" },
];

async function upsertUser({ name, email, password, role, createdBy }) {
  const hashedPassword = await bcrypt.hash(password, 10);
  return User.findOneAndUpdate(
    { email },
    { name, email, password: hashedPassword, role, createdBy },
    { upsert: true, new: true, setDefaultsOnInsert: true }
  );
}

async function uploadSample(buffer, eventId, photoId) {
  return new Promise((resolve, reject) => {
    const stream = cloudinary.uploader.upload_stream(
      {
        resource_type: "image",
        type: "authenticated",
        folder: `trizen/events/${eventId}`,
        public_id: String(photoId),
        overwrite: false,
      },
      (error, result) => (error ? reject(error) : resolve(result))
    );
    stream.end(buffer);
  });
}

async function main() {
  await mongoose.connect(MONGODB_URL);
  console.log("Connected to MongoDB.");

  const admin = await upsertUser({ ...DEMO.admin, role: "admin" });
  const team = await upsertUser({ ...DEMO.team, role: "team_member", createdBy: admin._id });

  let event = await Event.findOne({ name: DEMO.eventName, createdBy: admin._id });
  if (!event) {
    event = await Event.create({
      name: DEMO.eventName,
      createdBy: admin._id,
      assignedTeam: [team._id],
    });
  } else if (!event.assignedTeam.some((id) => String(id) === String(team._id))) {
    event.assignedTeam.push(team._id);
    await event.save();
  }

  const existingPhotoCount = await Photo.countDocuments({ eventId: event._id });

  if (existingPhotoCount === 0) {
    for (const sample of SAMPLE_PHOTOS) {
      const buffer = Buffer.from(sample.base64, "base64");
      const photo = new Photo({
        eventId: event._id,
        uploadedBy: team._id,
        filename: sample.filename,
        selectedForGallery: true,
      });
      const uploaded = await uploadSample(buffer, event._id, photo._id);
      photo.set({
        storageProvider: "cloudinary",
        cloudinaryPublicId: uploaded.public_id,
        cloudinaryAssetId: uploaded.asset_id,
        cloudinaryVersion: uploaded.version,
        cloudinaryFormat: uploaded.format,
        contentType: "image/jpeg",
        fileSize: uploaded.bytes,
      });
      await photo.save();
    }
    console.log(`Seeded ${SAMPLE_PHOTOS.length} sample photos in Cloudinary, all selected for the gallery.`);
  } else {
    console.log(`Event already has ${existingPhotoCount} photo(s). Run npm run migrate:cloudinary for legacy GridFS records.`);
  }

  const firstPhoto = await Photo.findOne({ eventId: event._id, cloudinaryPublicId: { $exists: true } });
  if (firstPhoto && !event.coverPhotoCloudinaryPublicId) {
    event.coverPhotoStorageProvider = "cloudinary";
    event.coverPhotoCloudinaryPublicId = firstPhoto.cloudinaryPublicId;
    event.coverPhotoCloudinaryAssetId = firstPhoto.cloudinaryAssetId;
    event.coverPhotoCloudinaryVersion = firstPhoto.cloudinaryVersion;
    event.coverPhotoCloudinaryFormat = firstPhoto.cloudinaryFormat;
    event.coverPhotoContentType = firstPhoto.contentType || "image/jpeg";
    await event.save();
  }

  if (!event.galleryPublished) {
    event.galleryPinHash = await bcrypt.hash(DEMO.pin, 10);
    event.gallerySlug = DEMO.slug;
    event.galleryPublished = true;
    try {
      await event.save();
    } catch (err) {
      if (err.code === 11000) {
        console.warn(`Slug "${DEMO.slug}" is already taken by another event — leaving this gallery unpublished. Publish it manually from the admin panel instead.`);
        event.gallerySlug = undefined;
        event.galleryPinHash = undefined;
        event.galleryPublished = false;
        await event.save();
      } else {
        throw err;
      }
    }
  }

  console.log("\nDemo data ready.\n");
  console.log(`Admin login:        ${DEMO.admin.email} / ${DEMO.admin.password}`);
  console.log(`Team member login:  ${DEMO.team.email} / ${DEMO.team.password}`);
  console.log(`Event:              ${DEMO.eventName}`);
  if (event.galleryPublished) {
    console.log(`Gallery link:       http://localhost:${PORT}/gallery/${event.gallerySlug}`);
    console.log(`Gallery PIN:        ${DEMO.pin}`);
  } else {
    console.log("Gallery:            not published yet — publish it from the admin panel.");
  }

  await mongoose.disconnect();
}

main().catch((err) => {
  console.error("Seed failed:", err);
  process.exit(1);
});
